import os
import re
from typing import Any, Dict, List, Optional, Tuple

import requests


PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _normalize_text(text: str) -> str:
    if text is None:
        return ""
    return text


def _default_requested_attributes() -> Dict[str, Dict[str, Any]]:
    return {
        "TOXICITY": {},
        "SEVERE_TOXICITY": {},
        "IDENTITY_ATTACK": {},
        "INSULT": {},
        "PROFANITY": {},
        "THREAT": {},
        "SEXUALLY_EXPLICIT": {},
    }


def _build_perspective_request(text: str, languages: Optional[List[str]] = None) -> Dict[str, Any]:
    payload: Dict[str, Any] = {
        "comment": {"text": text},
        "requestedAttributes": _default_requested_attributes(),
        "doNotStore": True,
    }
    if languages:
        payload["languages"] = languages
    return payload


def _attribute_scores(response_json: Dict[str, Any]) -> Dict[str, float]:
    scores: Dict[str, float] = {}
    attrs = response_json.get("attributeScores", {}) or {}
    for name, data in attrs.items():
        try:
            scores[name] = float(data["summaryScore"]["value"])
        except Exception:
            continue
    return scores


def _unsafe_thresholds() -> Dict[str, float]:
    return {
        "TOXICITY": 0.80,
        "SEVERE_TOXICITY": 0.70,
        "IDENTITY_ATTACK": 0.70,
        "INSULT": 0.80,
        "PROFANITY": 0.85,
        "THREAT": 0.50,
        "SEXUALLY_EXPLICIT": 0.70,
    }


def _find_unsafe_spans(text: str) -> List[Dict[str, Any]]:
    spans: List[Dict[str, Any]] = []

    patterns: List[Tuple[str, str, float]] = [
        (r"\b(?:kill|murder|stab|shoot)\b", "THREAT", 0.50),
        (r"\b(?:idiot|stupid|moron|dumb)\b", "INSULT", 0.80),
        (r"\b(?:fuck|shit|asshole|bitch)\b", "PROFANITY", 0.85),
        (r"\b(?:nigger|faggot|kike|spic|retard)\b", "IDENTITY_ATTACK", 0.70),
        (r"\b(?:sex|porn|nude|explicit)\b", "SEXUALLY_EXPLICIT", 0.70),
    ]

    for pattern, category, score in patterns:
        for match in re.finditer(pattern, text, flags=re.IGNORECASE):
            spans.append(
                {
                    "start": match.start(),
                    "end": match.end(),
                    "category": category,
                    "score": score,
                    "text": text[match.start() : match.end()],
                }
            )

    spans.sort(key=lambda s: (s["start"], -s["end"]))
    merged: List[Dict[str, Any]] = []
    for span in spans:
        if not merged or span["start"] >= merged[-1]["end"]:
            merged.append(span)
        else:
            if span["end"] > merged[-1]["end"]:
                merged[-1]["end"] = span["end"]
                merged[-1]["text"] = text[merged[-1]["start"] : merged[-1]["end"]]
            merged[-1]["score"] = max(merged[-1]["score"], span["score"])
            merged[-1]["category"] = merged[-1]["category"] + "," + span["category"]
    return merged


def _redact_spans(text: str, spans: List[Dict[str, Any]], replacement: str = "[REDACTED]") -> str:
    if not spans:
        return text
    spans = sorted(spans, key=lambda s: s["start"])
    out = []
    cursor = 0
    for span in spans:
        start = max(0, int(span["start"]))
        end = min(len(text), int(span["end"]))
        if start < cursor:
            continue
        out.append(text[cursor:start])
        out.append(replacement)
        cursor = end
    out.append(text[cursor:])
    return "".join(out)


def moderate_text(
    text: str,
    mode: str = "flag",
    languages: Optional[List[str]] = None,
    timeout: float = 15.0,
) -> Dict[str, Any]:
    """
    Uses Perspective API comments:analyze to flag potentially unsafe content.

    Args:
        text: Input text.
        mode: "flag" to return unsafe spans, "redact" to return redacted text and spans.
        languages: Optional language hint list for Perspective API.
        timeout: HTTP timeout in seconds.

    Returns:
        Dictionary with analysis results.
    """
    text = _normalize_text(text)
    api_key = os.getenv("PERSPECTIVE_API_KEY")

    response_json: Dict[str, Any] = {}
    scores: Dict[str, float] = {}
    service_error: Optional[str] = None

    if api_key and text:
        try:
            resp = requests.post(
                PERSPECTIVE_API_URL,
                params={"key": api_key},
                json=_build_perspective_request(text, languages=languages),
                timeout=timeout,
            )
            resp.raise_for_status()
            response_json = resp.json() or {}
            scores = _attribute_scores(response_json)
        except Exception as exc:
            service_error = str(exc)

    thresholds = _unsafe_thresholds()
    detected_categories = [
        category
        for category, score in scores.items()
        if score >= thresholds.get(category, 0.8)
    ]

    spans = _find_unsafe_spans(text)
    if not spans and detected_categories:
        lower_text = text.lower()
        for category in detected_categories:
            if category == "THREAT":
                patterns = [r"\b(?:kill|murder|stab|shoot)\b"]
            elif category == "INSULT":
                patterns = [r"\b(?:idiot|stupid|moron|dumb)\b"]
            elif category == "PROFANITY":
                patterns = [r"\b(?:fuck|shit|asshole|bitch)\b"]
            elif category == "IDENTITY_ATTACK":
                patterns = [r"\b(?:nigger|faggot|kike|spic|retard)\b"]
            elif category == "SEXUALLY_EXPLICIT":
                patterns = [r"\b(?:sex|porn|nude|explicit)\b"]
            else:
                patterns = []
            for pattern in patterns:
                for match in re.finditer(pattern, lower_text, flags=re.IGNORECASE):
                    spans.append(
                        {
                            "start": match.start(),
                            "end": match.end(),
                            "category": category,
                            "score": scores.get(category, 0.0),
                            "text": text[match.start() : match.end()],
                        }
                    )
        spans.sort(key=lambda s: (s["start"], -s["end"]))

    unsafe = bool(spans or detected_categories)

    result: Dict[str, Any] = {
        "unsafe": unsafe,
        "categories": detected_categories,
        "scores": scores,
        "unsafe_spans": spans,
        "provider": "Perspective API",
        "provider_error": service_error,
    }

    if mode == "redact":
        result["redacted_text"] = _redact_spans(text, spans)
    else:
        result["redacted_text"] = text

    return result


if __name__ == "__main__":
    import json
    import sys

    input_text = sys.stdin.read()
    output = moderate_text(input_text, mode=os.getenv("MODERATION_MODE", "flag"))
    print(json.dumps(output, ensure_ascii=False, indent=2))
